/* Portfolio continuity: local demo state, governed context and linked work. */
const ct={schema:1,contexts:[],decisions:[],tasks:{},findings:{},runs:{},dismissed:{},reuse:{},pins:[],next:1,storage:'loading',modal:null,loaded:false};
const ctTimers=new Map(),ctMonths=['June','July','August','September','October'],ctShort=['Jun','Jul','Aug','Sep','Oct'];
const ctLabels={ready:'Ready to continue',running:'Agent working',paused:'Paused',waiting_info:'Waiting for information',waiting_data:'Waiting for data',review:'Ready for review',monitoring:'Monitoring',resolved:'Reviewed'};
const ctIssueNames={northstar:'Support cost follow-up',cedar:'Cost-gap clarification',harbor:'Growth repeatability review'};
const ctQuestions={northstar:['Was Support capacity added ahead of a customer rollout? Provide the staffing plan and customer go-live dates.','Are the Support costs recurring? Separate base pay, overtime, contractors and one-off items.','How did ticket volumes and service levels change?'],cedar:['Explain September’s additional $10k in Support and $20k in other departments. Were the changes temporary?','Provide the payroll bridge, contractor invoices and service volumes.','Does revenue-recognition timing differ from delivery? Provide the schedule; no operating plan has been supplied.'],harbor:['Provide a revenue bridge by customer and recurring versus one-time work.','Confirm capacity utilization, staffing changes and service levels.','Which delivery-model changes could explain the trend?']};
const ctHypotheses={northstar:'Support capacity may have been added ahead of customer demand. No hiring plan or customer-launch evidence has been supplied.',cedar:'Staffing, compensation or revenue-recognition timing may explain the wider gap. These explanations remain unverified.',harbor:'Customer mix, revenue timing or delayed hiring could explain the improving cost ratio. Workforce productivity has not been established.'};
const ctClone=x=>JSON.parse(JSON.stringify(x));
const ctId=p=>p+'-'+ct.next++;
const ctButton=(label,action,value='',primary=false)=>`<button type="button" class="as-button ${primary?'primary':''}" data-ct="${action}" data-ct-value="${esc(value)}">${label}</button>`;
function ctSourceRefs(ids,end=3,start=0){return ids.flatMap(id=>['hr','finance'].flatMap(type=>Array.from({length:end-start+1},(_,n)=>{const month=start+n;return {company:id,type,publication:`${id.toUpperCase()}-${type==='hr'?'HR':'FIN'}-2026-${String(month+6).padStart(2,'0')}-v1`,system:sourceSystems[id][type],period:ctMonths[month]+' 2026',status:id==='harbor'&&type==='finance'&&month===3?'Approved publication; subsequent refresh delayed':'Approved synthetic publication'};})));}
function ctReviewQuestions(id,start=0,end=3){if(id!=='cedar')return ctQuestions[id];const d=data[id],sd=Math.round((d.support[end]-d.support[start])*1000),other=Math.round((d.cost[end]-d.cost[start]-(d.support[end]-d.support[start]))*1000);return [`Explain the $${sd}k Support change and $${other}k change in other departments from ${ctMonths[start]} to ${ctMonths[end]}. Were these staffing, compensation, contractor or classification changes?`,'Provide the payroll bridge, contractor invoices and service volumes.','Does revenue-recognition timing differ from delivery? Provide the schedule; no operating plan has been supplied.'];}
function ctHypothesisFor(id,context){return context.filter(c=>c.company===id&&c.kind==='hypothesis').at(-1)?.text||'No hypothesis is included in this context. The business cause has not been established.';}

function ctMetrics(id,start=0,end=3){const d=data[id],cg=pct(d.cost[end],d.cost[start]),rg=pct(d.revenue[end],d.revenue[start]),delta=d.cost[end]-d.cost[start],sd=d.support[end]-d.support[start];return{id,cg,rg,gap:cg-rg,cost:d.cost[end],revenue:d.revenue[end],support:d.support[end],delta,sd,ratio:d.cost[end]/d.revenue[end]*100,ratio0:d.cost[start]/d.revenue[start]*100,share:Math.abs(delta)<1e-9?null:sd/delta*100};}
function ctFact(id,start=0,end=3){const m=ctMetrics(id,start,end);return `${ctMonths[start]}–${ctMonths[end]}: people cost ${p(m.cg)}, revenue ${p(m.rg)}; growth gap ${signedPP(m.gap)}. Support contributed $${Math.round(m.sd*1000)}k of the $${Math.round(m.delta*1000)}k change in monthly people cost.`;}
function ctContextEntries(ids){return ct.contexts.filter(c=>ids.includes(c.company)&&!c.superseded);}
function ctLatestDecision(id){return [...ct.decisions].reverse().find(d=>d.company===id);}
function ctTask(key=state.session){if(!ct.tasks[key]){const ids=taskCompanyIds(key);ct.tasks[key]={key,ids:[...ids],issue:ids.length===1?ids[0]:null,goal:taskTitle(key),status:'ready',step:0,activity:[],token:0,next:'Choose the next analysis or question.',contextIds:ctContextEntries(ids).map(c=>c.id)};}return ct.tasks[key];}
function ctActivity(t,text){t.activity.push({at:new Date().toISOString(),text});t.activity=t.activity.slice(-40);}
function ctContextSnapshot(ids,key=null){const excluded=ct.tasks[key]?.excluded||[];return ctClone(ctContextEntries(ids).filter(c=>!excluded.includes(c.id)));}
function ctCapturePlanContext(plan){plan.contextSnapshot=ctContextSnapshot(plan.ids,plan.taskKey);plan.contextScope=[...plan.ids];plan.decisionIds=plan.ids.map(id=>ctLatestDecision(id)?.id||null);return plan;}
function ctEndIndex(end){if(typeof end==='number')return end;const i=['jun','jul','aug','sep','oct'].indexOf(String(end).slice(0,3).toLowerCase());return i>=0?i:3;}
function ctWantsDeliverable(text){return /\b(?:create|build|make|generate|prepare|update|refresh|draft)\b.*\b(?:brief|report|table|review|memo|scorecard)\b|(?:生成|制作|准备|更新|写).*(?:简报|报告|表格)/i.test(text);}
function ctEnsureIssue(id){let key=state.caseSessions[id];if(!key||!taskSnapshot(key)||taskCompanyIds(key).length!==1||taskCompanyIds(key)[0]!==id){const a=createOpsTask({...caseConfig(id)},names[id]+' · '+ctIssueNames[id],ctFact(id,0,2)+' The business explanation is still open.');key=a.key;state.caseSessions[id]=key;state.sessions[key].contextCase=id;state.artifacts.find(x=>x.id===a.id).fromCase=id;}const t=ctTask(key);t.issue=id;t.ids=[id];t.goal=ctIssueNames[id];return key;}
function ctFinding(id,end=2){const fid='F-'+id,entry=ct.findings[fid];if(!entry)ct.findings[fid]={id:fid,company:id,versions:[]};const f=ct.findings[fid];let v=f.versions.find(v=>v.end===end);if(!v){v={version:f.versions.length+1,end,start:0,fact:ctFact(id,0,end),hypothesis:ctHypotheses[id],questions:[...ctQuestions[id]],sources:ctSourceRefs([id],end),context:ctContextSnapshot([id]),createdAt:new Date().toISOString()};f.versions.push(v);}return {id:fid,company:id,version:v.version,...ctClone(v)};}
function ctPlan(t){return {ids:[...t.ids],start:0,end:t.period?.includes('August')&&!t.period?.includes('September')?2:3,focus:'total',format:t.id==='scorecard'?'table':'brief',action:t.action||'analyze',title:t.title,goal:t.reason,issue:t.issue||null,taskKey:t.taskKey||null,origin:t.key,source:t.sourceSnapshot?ctClone(t.sourceSnapshot):null,contextSnapshot:ctContextSnapshot(t.ids,t.taskKey),decisionIds:t.ids.map(id=>ctLatestDecision(id)?.id||null)};}
function ctPlanKey(p){return JSON.stringify([p.ids,p.start,p.end,p.focus,p.format,p.action,p.source?.id,p.source?.version,p.contextSnapshot?.map(c=>[c.id,c.version]),p.decisionIds]);}
function ctPlanText(p){return `${p.action==='request'?'Prepare an evidence request':p.action==='challenge'?'Challenge the finding':'Analyze '+(p.focus==='support'?'Support cost':'people cost')+' and revenue'} for ${scopeName(p.ids)}, ${ctMonths[p.start]}–${ctMonths[p.end]} 2026. ${p.format==='brief'?'Create a one-page brief':p.format==='table'?'Create a comparison table':'Create an analytical report'}. Keep assumptions separate from source facts.`;}
function ctPlanSummary(p){return `<div class="ct-plan-chips"><span>${esc(scopeName(p.ids))}</span><span>${ctShort[p.start]} → ${ctShort[p.end]} 2026</span><span>${p.focus==='support'?'Support focus':'People cost + revenue'}</span><span>${p.format==='brief'?'One-page brief':p.format==='table'?'Comparison table':'Analytical report'}</span></div>`;}
function ctResolveInput(text,base){
 const q=text.toLowerCase(),next=ctClone(base),aliases={northstar:'northstar|北极星',cedar:'cedar|雪松',harbor:'harbor|港湾'};
 const mentioned=Object.keys(data).filter(id=>new RegExp(aliases[id]).test(q));
 if(/all (?:three )?companies|whole portfolio|所有公司|全部公司|整个组合/.test(q))next.ids=Object.keys(data);
 const exclusion=q.match(/(?:exclude|excluding|except|without|remove|排除|除了|去掉|移除)\s+([^;.。；]+)/);
 if(exclusion){const excluded=mentioned.filter(id=>new RegExp(aliases[id]).test(exclusion[1]));next.ids=next.ids.filter(id=>!excluded.includes(id));}
 else if(mentioned.length)next.ids=/\b(?:add|include)\b|添加|加入/.test(q)?[...new Set([...next.ids,...mentioned])]:mentioned;
 const unsupportedMonths=/\b(?:january|jan|february|feb|march|mar|april|apr|may|october|oct|november|nov|december|dec)\b|(?:十一|十二|一|二|三|四|五|十)月|(?:^|\D)(?:1[012]|[1-5])月/.test(q);
 const unsupportedYear=[...q.matchAll(/\b(20\d{2})\b/g)].some(m=>m[1]!=='2026');
 if(unsupportedMonths||unsupportedYear)return{error:'That period is unavailable. Approved demo publications cover June–September 2026. No substitute period was used.'};
 const found=[/june|\bjun\b|六月|6月/,/july|\bjul\b|七月|7月/,/august|\baug\b|八月|8月/,/september|\bsep\b|九月|9月/].flatMap((r,i)=>r.test(q)?[i]:[]);
 if(found.length>1){next.start=Math.min(...found);next.end=Math.max(...found);}else if(found.length===1){next.end=found[0];if(next.start>=next.end)next.start=0;}
 if(!next.ids.length)return{error:'This selection excludes every company. Choose at least one company.'};
 return{plan:next,recognized:!!mentioned.length||!!found.length||/all companies|whole portfolio|所有公司|全部公司/.test(q)};
}
function ctInterpret(text,base){
 const q=text.toLowerCase(),resolved=ctResolveInput(text,base);if(resolved.error)return resolved;const plan=resolved.plan;
 if(/headcount|salary|salaries|attrition|ebitda|forecast|budget|预算|人数|薪资|离职|预测/.test(q))return{error:'That field is unavailable. This demo supports aggregate people cost, Support cost and revenue. The plan was not changed.'};
 if(/support|客服|支持/.test(q))plan.focus='support';if(/total people|all people|全部人员|总人工/.test(q))plan.focus='total';
 if(/one.page|brief|简报|一页/.test(q))plan.format='brief';else if(/table|scorecard|表格|对比表/.test(q))plan.format='table';else if(/report|报告/.test(q))plan.format='report';
 if(ctWantsDeliverable(q))plan.action=/evidence request|information request|review agenda|问题清单|资料请求/.test(q)?'request':/challenge|质疑/.test(q)?'challenge':'analyze';
 if(plan.start>=plan.end)return{error:'Select two different months for a comparison.'};
 if(!resolved.recognized&&!/support|people|revenue|brief|table|report|scorecard|客服|支持|成本|收入|简报|一页|表格|报告/.test(q))return{error:'Specify companies, a month range, a cost focus or an output format. You can also use the controls below.'};
 plan.issue=plan.ids.length===1?plan.ids[0]:null;plan.title=scopeName(plan.ids)+' · '+ctMonths[plan.end]+' '+(plan.format==='table'?'comparison':plan.format==='brief'?'follow-up brief':'analysis');plan.goal=ctPlanText(plan);plan.contextSnapshot=ctContextSnapshot(plan.ids,plan.taskKey);plan.decisionIds=plan.ids.map(id=>ctLatestDecision(id)?.id||null);return{plan};
}

const ctBaseFeedTasks=feedTasks;
feedTasks=function(selectedIds=companyScope()){
 const ids=Object.keys(data).filter(id=>selectedIds.includes(id)),out=[];
 for(const id of ids){const key=ctEnsureIssue(id),task=ctTask(key),decision=ctLatestDecision(id),run=ops.runs.find(r=>r.config.ctLink?.company===id&&r.status==='Completed'),reviewed=task.status==='resolved'||task.status==='monitoring';if(reviewed&&!task.needsRevisit)continue;
 if(task.status==='waiting_data'){out.push({id:'ct-'+id,key:'ct-'+id+'|'+id,ids:[id],scope:names[id],title:names[id].split(' ')[0]+' follow-up is waiting for October',reason:'The linked judgment is retained. The next comparison will be available after October reporting is approved.',period:'October 2026 · awaiting data',output:'Linked investigation',icon:'clock-3',action:'analyze',issue:id,taskKey:key,waiting:true,score:30,why:'Latest approved publication: September',steps:[]});continue;}
 const review=task.status==='review',hasRun=!!run&&task.needsRevisit;
 const title=hasRun?`Review ${names[id].split(' ')[0]}’s follow-up result`:id==='northstar'?'Revisit Northstar’s Support cost follow-up':id==='cedar'?'Resolve Cedar’s widening cost gap':'Validate Harbor’s improvement';
 const reason=hasRun?run.summary:id==='northstar'?'September is available. Support cost is flat while revenue rose 8.6% from August.':id==='cedar'?'The June-baseline growth gap widened from 5.0 pp to 6.2 pp. The operating explanation is still missing.':'Revenue continues to grow faster than people cost. Check alternative explanations before calling this an efficiency gain.';
 out.push({id:'ct-'+id,key:'ct-'+id+'|'+id,ids:[id],scope:names[id],title,reason,period:'June–September 2026',output:id==='cedar'?'Evidence request draft':id==='harbor'?'Finding review':'Follow-up brief',icon:id==='cedar'?'list-checks':id==='harbor'?'shield-check':'file-text',action:id==='cedar'?'request':id==='harbor'?'challenge':'analyze',issue:id,taskKey:key,completedRun:hasRun?{key,id:run.outputId}:null,score:hasRun?110:review?105:task.status==='waiting_info'?98:id==='northstar'?90:80,why:hasRun?`Linked to ${run.id} and decision ${run.config.ctLink.decisionId}`:decision?`Continues ${decision.id}: ${decision.revisit}`:id==='northstar'?'Continues your saved August Support investigation':id==='cedar'?'Unresolved business context; new September movement':'Interpretation remains unverified',prompt:'',steps:['Load the original finding and approved monthly publications','Compare the new data with the existing questions','Prepare the next deliverable and retain unresolved assumptions']});}
 for(const t of ctBaseFeedTasks(ids)){const source=t.sourceId?state.artifacts.find(a=>a.id===t.sourceId):null;const captured=source?.versions[t.sourceVersion];out.push({...t,score:t.id==='brief'?70:50,action:t.id==='agenda'?'request':'analyze',why:t.id==='brief'&&captured?`New September data is available; saved brief v${t.sourceVersion+1} ends in August`:'Prepared from your selected companies and current review questions',sourceSnapshot:captured?{id:source.id,version:t.sourceVersion,value:ctClone(captured)}:null});}
 return out.map(t=>({...t,prompt:ctPlanText(ctPlan(t))})).filter(t=>!ct.dismissed[t.key]).sort((a,b)=>b.score-a.score);
};
// Home is one task list. Existing reports share Review, regardless of origin.
function ctHomeArtifact(id,key,ids){
 const a=state.artifacts.find(a=>a.id===Number(id)),cfg=a?.versions?.at(-1);
 if(!cfg||cfg.empty||cfg.ctArtifact?.kind==='decision'||(key&&a.session!==key))return null;
 if(JSON.stringify([...cfg.companyIds].sort())!==JSON.stringify([...ids].sort()))return null;
 return {id:a.id,key:a.session,cfg};
}
function ctHomePrepared(id){
 const company=!!caseDefs[id],ids=company?[id]:Object.keys(data),sum=(field,i)=>ids.reduce((n,k)=>n+data[k][field][i],0);
 const cost=sum('cost',2),cost0=sum('cost',0),revenue=sum('revenue',2),revenue0=sum('revenue',0),sd=sum('support',2)-sum('support',0);
 const titles={northstar:'People costs outpace revenue',cedar:'Support is driving the cost increase',harbor:'Revenue growth leads cost growth',burden:'Portfolio cost intensity is rising',support:'Support is the main cost driver',mix:'Harbor delivers half the revenue gain'};
 const summary=id==='cedar'||id==='support'?`${(sd/(cost-cost0)*100).toFixed(1)}% of cost increase from Support · $${Math.round(sd*1000)}k`:id==='burden'?`Cost / revenue ${(cost/revenue*100).toFixed(1)}% · ${signedPP((cost/revenue-cost0/revenue0)*100)}`:id==='mix'?'$800k · 50% of portfolio revenue growth':`People cost ${pPct(cost,cost0)} · Revenue ${pPct(revenue,revenue0)}`;
 return {key:'finding-'+id,finding:id,ids,company:company?names[id]:'Portfolio',title:titles[id],summary,period:'Jun–Aug 2026',type:'review',target:company?'case':'portfolio',score:company?80:60,detail:'Prepared analysis from the June–August HR and financial publications.'};
}
function ctHomeOutput(entry,out){
 const a=out.cfg,p=a.ctPlan||{ids:a.companyIds,start:0,end:ctEndIndex(a.end),focus:a.basis==='support'?'support':'total'},sum=(field,i)=>p.ids.reduce((n,id)=>n+data[id][field][i],0),cost=p.focus==='support'?'support':'cost';
 return {...entry,target:'artifact',artifactId:out.id,taskKey:out.key,plan:p,period:ctShort[p.start]+'–'+ctShort[p.end]+' 2026',summary:a.ctArtifact?.kind==='request'?'Management review questions and the evidence to request.':`${cost==='support'?'Support cost':'People cost'} ${pPct(sum(cost,p.end),sum(cost,p.start))} · Revenue ${pPct(sum('revenue',p.end),sum('revenue',p.start))}`,detail:a.ctArtifact?.kind==='request'?'An unsent draft for your review. Open the report to inspect and refine the questions.':'Review the prepared result and its supporting source values.',type:'review',score:110};
}
function ctHomeEntries(){
 const tasks=feedTasks(),entries=[];
 for(const id of scopedFindings()){
  const e=ctHomePrepared(id),t=tasks.find(t=>t.issue===id),key=state.caseSessions[id],progress=key&&ct.tasks[key];
  if(caseDefs[id]&&progress&&['resolved','monitoring'].includes(progress.status)&&!progress.needsRevisit)continue;
  if(t){e.key='issue-'+id;e.task=t;e.taskKey=key;e.score=t.score;const candidates=[progress?.outputId,...ops.runs.filter(r=>r.taskKey===key&&r.status==='Completed').map(r=>r.outputId),...state.artifacts.filter(a=>a.session===key&&a.versions.at(-1)?.ctArtifact).map(a=>a.id)];
   const output=candidates.map(a=>ctHomeArtifact(a,key,[id])).filter(Boolean).sort((a,b)=>b.id-a.id)[0];
   if(output){Object.assign(e,ctHomeOutput(e,output));e.title=id==='northstar'?'Support cost follow-up':id==='cedar'?'Cost-gap investigation':'Revenue growth review';}
   if(['running','paused','waiting_data'].includes(progress?.status)){e.type='active';e.target='task';e.summary=progress.status==='waiting_data'?'Next follow-up is waiting for October reporting.':progress.status==='paused'?'Analysis paused. Resume from the saved progress.':'The agent is preparing the next analysis.';e.status=progress.status==='running'?'In progress':progress.status==='paused'?'Paused':'Waiting for data';e.plan=progress.plan||e.plan;e.period=progress.status==='waiting_data'?'October · awaiting data':e.plan?ctShort[e.plan.start]+'–'+ctShort[e.plan.end]+' 2026':e.period;e.detail=progress.next;e.score=progress.status==='waiting_data'?35:115;}
  }
  entries.push(e);
 }
 for(const t of tasks.filter(t=>!t.issue)){
  const e={key:'workflow-'+t.key,ids:t.ids,company:t.scope,title:t.title,summary:t.reason,period:'Jun–'+(t.id==='agenda'?'Aug':'Sep')+' 2026',type:'run',target:'run',task:t,score:50,detail:t.why};
  const matching=Object.entries(ct.runs).filter(([fingerprint])=>fingerprint.startsWith(t.key+'|')).map(([,r])=>r),outputs=matching.map(r=>ctHomeArtifact(r.id,r.key,t.ids)).filter(Boolean).sort((a,b)=>b.id-a.id);
  if(outputs.length){Object.assign(e,ctHomeOutput(e,outputs[0]));e.title=t.id==='brief'?ctMonths[e.plan.end]+' partner brief':t.id==='scorecard'?ctMonths[e.plan.end]+' operating scorecard':'Management review questions';}
  const active=matching.map(r=>ct.tasks[r.key]).find(r=>r&&['running','paused'].includes(r.status)&&JSON.stringify([...r.ids].sort())===JSON.stringify([...t.ids].sort()));
  if(active){e.type='active';e.target='task';e.taskKey=active.key;e.plan=active.plan;e.period=ctShort[e.plan.start]+'–'+ctShort[e.plan.end]+' 2026';e.title=t.id==='brief'?ctMonths[e.plan.end]+' partner brief':t.id==='scorecard'?ctMonths[e.plan.end]+' operating scorecard':'Management review questions';e.status=active.status==='running'?'In progress':'Paused';e.summary=active.next;e.score=115;}
  entries.push(e);
 }
 return entries.sort((a,b)=>b.score-a.score);
}
function ctHomeReviewButton(e){const label=e.type==='review'?'Review':e.type==='run'?'Run':'Open task',icon=e.type==='run'?'play':'arrow-up-right';
 if(e.target==='case'||e.target==='portfolio')return `<button type="button" class="as-button ct-home-primary" ${e.target==='case'?'data-case':'data-feed-report'}="${e.finding}" aria-label="Review: ${esc(e.title)}">Review ${I(icon)}</button>`;
 return ctButton(label+' '+I(icon),e.target==='artifact'?'open-output':e.target==='task'?'open-task':'run-plan',e.target==='artifact'?e.artifactId:e.target==='task'?e.taskKey:e.task.id).replace('class="as-button ', 'aria-label="'+label+': '+esc(e.title)+'" class="as-button ct-home-primary ');
}
function ctHomeCard(e){const expanded=!!feedState.open['home:'+e.key],previewId='ct-home-preview-'+e.key.replace(/[^a-z0-9-]/gi,'-');
 const preview=e.type==='active'?`<p>${esc(e.summary)}</p>${e.status!=='Waiting for data'&&e.plan?ctPlanSummary(e.plan):''}`:e.type==='run'?`${ctPlanSummary(ctPlan(e.task))}<p>${esc(e.task.prompt)}</p><ol>${e.task.steps.map(s=>'<li>'+esc(s)+'</li>').join('')}</ol>`:e.plan?ctTrend(e.plan):e.finding?findingQuickView(e.finding):'';
 const next=e.task&&e.target==='case'?`<div class="ct-home-next"><span>Next analysis · September</span>${ctButton(e.finding==='cedar'?'Draft review questions':e.finding==='harbor'?'Check the interpretation':'Compare September','run-plan',e.task.id)}</div>`:'';
 return `<article class="ct-home-card ${expanded?'is-expanded':''}" data-home-card="${esc(e.key)}"><div class="ct-home-meta"><span>${I(e.ids.length===1?'building-2':'layers-2')}${esc(e.company)}</span><span>${esc(e.period)}</span></div><h2>${esc(e.title)}</h2><p class="ct-home-summary">${esc(e.summary)}</p><div class="ct-home-actions"><button type="button" class="ct-home-preview" data-ct="home-preview" data-ct-value="${esc(e.key)}" aria-expanded="${expanded}" aria-controls="${previewId}" aria-label="${expanded?'Hide preview':'Preview'}: ${esc(e.title)}">${expanded?'Less':'Preview'} ${I(expanded?'chevron-up':'chevron-down')}</button><div>${e.status?`<span class="ct-home-status">${esc(e.status)}</span>`:''}${e.type==='run'?ctButton('Adjust','adjust',e.task.id):''}${ctHomeReviewButton(e)}</div></div><div class="ct-home-detail" id="${previewId}" ${expanded?'':'hidden'}>${expanded?preview+'<p class="ct-home-note">'+esc(e.detail||'The task retains the original report and its source history.')+'</p>'+next:''}</div></article>`;
}
const ctBaseHome=homeWorkbench;
homeWorkbench=function(){const entries=ctHomeEntries(),filter=['all','review','run'].includes(feedState.homeFilter)?feedState.homeFilter:'all',shown=entries.filter(e=>filter==='all'||e.type===filter);return `<section class="bf-briefing ct-home" aria-label="Portfolio tasks"><header class="bf-header"><div><div class="as-kicker">YOUR PORTFOLIO WORK</div><h1>What’s worth your attention.</h1><p>Review prepared work or start the next analysis.</p></div><div class="ct-briefing-tools">${ctButton(I('book-open')+' Company context','context')}<span class="ct-storage">${ct.storage==='saved'?'Saved in this browser':ct.storage==='unavailable'?'Saved for this visit':'Local demo'}</span></div></header><div class="bf-toolbar"><div class="bf-filters" role="group" aria-label="Task actions">${[['all','All tasks',entries.length],['review','To review',entries.filter(e=>e.type==='review').length],['run','To run',entries.filter(e=>e.type==='run').length]].map(([id,label,n])=>`<button type="button" data-ct="home-filter" data-ct-value="${id}" aria-pressed="${filter===id}">${label}<span>${n}</span></button>`).join('')}</div><span class="ct-home-sort">${esc(scopeName())}</span></div><div class="ct-home-grid">${shown.length?shown.map(ctHomeCard).join(''):'<p class="ct-home-empty">No tasks in this view. Your previous work is available in Workspace.</p>'}</div></section>`;};
runFeedTask=function(id){const t=feedTasks().find(t=>t.id===id);if(t?.completedRun?.id)openHubArtifact(t.completedRun.id);else if(t)ctLaunch(ctPlan(t));};

function ctAddArtifact(key,plan,kind='analysis',extra={}){const id=++seq,cfg={...ctClone(initial),companyIds:[...plan.ids],end:plan.end===2?'aug':'sep',format:plan.format,basis:plan.focus,length:plan.format==='brief'?'short':'normal',blocks:[],title:scopeName(plan.ids)+' · '+(kind==='request'?'Evidence request':kind==='challenge'?'Finding review':kind==='decision'?'Review decision':ctMonths[plan.end]+' '+(plan.format==='table'?'comparison table':plan.format==='report'?'analytical report':'follow-up brief')),ctPlan:ctClone(plan),ctArtifact:{kind,context:ctClone(plan.contextSnapshot||ctContextSnapshot(plan.ids,key)),sourceBrief:plan.source?ctClone(plan.source):null,findings:plan.ids.map(id=>ctFinding(id,plan.end)),sources:ctSourceRefs(plan.ids,plan.end,plan.start),createdAt:new Date().toISOString(),...ctClone(extra)}};state.artifacts.push({id,session:key,fromCase:plan.issue||null,versions:[cfg],saved:{version:0,value:ctClone(cfg)}});const snap=taskSnapshot(key);snap.active=id;snap.view=null;if(key===state.session){state.active=id;state.view=null;state.selected=null;}else state.sessions[key]=snap;const message={role:'agent',text:kind==='decision'?'Your judgment is recorded with its evidence and revisit condition. Earlier decisions remain available.':kind==='request'?'The information request is ready as a draft. Nothing was sent; the task remains open until the missing context is supplied.':kind==='challenge'?'The numerical finding has been checked. Alternative explanations and missing evidence are recorded for your review.':'The analysis is ready for review. Source facts and unresolved business explanations remain separate.',meta:'Linked work · '+scopeName(plan.ids)+' · '+ctShort[plan.start]+'–'+ctShort[plan.end],artifactId:id,artifactVersion:1};if(key===state.session)state.messages.push(message);else state.sessions[key].messages.push(message);return id;}
function ctLaunch(plan,background=false){
 const p=ctClone(plan);if(!p.ids.length||p.start>=p.end||p.end>3)return null;
 const capturedScope=p.contextScope||[...new Set((p.contextSnapshot||[]).map(c=>c.company))];
 if(!p.contextSnapshot||JSON.stringify([...capturedScope].sort())!==JSON.stringify([...p.ids].sort()))ctCapturePlanContext(p);
 p.decisionIds??=p.ids.map(id=>ctLatestDecision(id)?.id||null);
 const fingerprint=(p.origin||'custom')+'|'+ctPlanKey(p),prior=ct.runs[fingerprint];
 if(prior&&taskSnapshot(prior.key)){ctCloseModal();if(prior.id)openHubArtifact(prior.id);else resumeTask(prior.key);return prior;}
 let key=p.taskKey;
 if(key&&JSON.stringify([...taskCompanyIds(key)].sort())!==JSON.stringify([...p.ids].sort()))key=null;
 if(!key&&p.ids.length===1&&p.issue)key=ctEnsureIssue(p.issue);
 if(!key){const a=createOpsTask({...initial,companyIds:p.ids,blocks:[]},p.title||'Portfolio investigation','The task is ready to begin.');key=a.key;state.artifacts.find(x=>x.id===a.id).versions[0].empty=true;state.sessions[key].messages=[];}
 const task=ctTask(key);ctPause(key,false);Object.assign(task,{ids:[...p.ids],issue:p.issue,goal:p.goal||p.title||ctPlanText(p),plan:p,status:'ready',step:0,next:'Run the approved analysis plan.',contextIds:p.contextSnapshot.map(c=>c.id),fingerprint});
 ct.runs[fingerprint]={key};ctActivity(task,'Plan prepared: '+ctPlanText(p));ctCloseModal();resumeTask(key);
 if(background)ctStart(key);else{const output=ctAddArtifact(key,p,p.action==='request'?'request':p.action==='challenge'?'challenge':'analysis');task.status=p.action==='request'?'waiting_info':'review';task.step=3;task.outputId=output;task.next=p.action==='request'?'Add the requested management context; no external request has been sent.':'Review the evidence, then record your judgment or keep monitoring.';ctActivity(task,'Analysis prepared. Human review is still required.');ct.runs[fingerprint].id=output;render();ctSave();}
 return{key,id:task.outputId};
}
function ctPause(key,record=true){const t=ctTask(key);t.token=(t.token||0)+1;if(ctTimers.has(key)){clearTimeout(ctTimers.get(key));ctTimers.delete(key);}if(t.status==='running'){t.status='paused';t.next='Resume the same task or take over the conversation.';if(record)ctActivity(t,'Paused by you; the draft and completed steps are retained.');}ctSave();}
function ctStart(key){const t=ctTask(key);if(['running','waiting_data','monitoring','resolved'].includes(t.status))return;if(!t.plan)t.plan={ids:[...t.ids],start:0,end:3,focus:'total',format:'brief',action:'analyze',issue:t.issue,goal:t.goal};if(t.plan.end>3){t.status='waiting_data';t.next='October publication is not available. Latest approved data ends in September.';ctActivity(t,t.next);ctRender();return;}if(t.step>=3){t.step=0;t.plan.contextSnapshot=ctContextSnapshot(t.ids,key);}t.plan.contextSnapshot??=ctContextSnapshot(t.ids,key);t.contextIds=t.plan.contextSnapshot.map(c=>c.id);t.status='running';t.next='The agent is working through your plan.';t.token=(t.token||0)+1;const token=t.token;ctActivity(t,'Started background analysis · Simulated while this page is open.');const steps=['Loaded approved source publications and the captured context.','Calculated the selected monthly comparison and checked prior findings.','Prepared the deliverable and unresolved review questions.'];const advance=()=>{if(t.token!==token||t.status!=='running')return;ctActivity(t,steps[t.step]);t.step++;if(t.step<3){ctTimers.set(key,setTimeout(advance,2800));}else{ctTimers.delete(key);t.outputId=ctAddArtifact(key,t.plan,t.plan.action==='request'?'request':t.plan.action==='challenge'?'challenge':'analysis');if(t.fingerprint&&ct.runs[t.fingerprint])ct.runs[t.fingerprint].id=t.outputId;t.status=t.plan.action==='request'?'waiting_info':'review';t.next=t.status==='waiting_info'?'Add missing management context; the request is an unsent draft.':'Review the result and record a judgment.';}ctRender();};ctTimers.set(key,setTimeout(advance,2800));ctRender();}
function ctWorkBar(){const t=ctTask(),related=ctContextSnapshot(t.ids,state.session),active=t.status==='running';return `<div class="ct-workbar"><button type="button" class="ct-state ${t.status}" data-ct="progress" data-ct-value="${state.session}">${active?I('loader-circle'):I(t.status==='waiting_info'?'circle-help':t.status==='review'?'circle-check':'activity')}<strong title="${esc(t.next)}">${ctLabels[t.status]}</strong>${I('chevron-down')}</button><div class="ct-workbar-actions">${ctButton(I('book-open')+' Context · '+related.length,'context',state.session)}${ctButton(I('bookmark-check')+'<span class="ct-judgment-label"> Judgment</span>','decision',t.issue||t.ids[0]).replace('<button ', '<button aria-label="Record judgment" ')}</div></div>`;}
const ctBaseConversation=conversation;
conversation=function(){const p=current().ctPlan||ct.tasks[state.session]?.plan;return p?ctBaseConversation().replace(/Jun–(?:Aug|Sep) 2026/g,ctShort[p.start]+'–'+ctShort[p.end]+' 2026'):ctBaseConversation();};
const ctBaseWorkspaceHeader=workspaceHeader;
workspaceHeader=function(){return ctBaseWorkspaceHeader().replace('</header>',ctWorkBar()+'</header>');};
function ctTrend(plan){const points=Array.from({length:plan.end-plan.start+1},(_,i)=>i+plan.start),sum=(k,i)=>plan.ids.reduce((n,id)=>n+data[id][k][i],0),cost=plan.focus==='support'?'support':'cost',series=[{label:cost==='support'?'Support cost':'People cost',color:'#2863c8',values:points.map(i=>sum(cost,i)/sum(cost,plan.start)*100)},{label:'Revenue',color:'#278577',values:points.map(i=>sum('revenue',i)/sum('revenue',plan.start)*100)}],lo=Math.floor((Math.min(...series.flatMap(s=>s.values))-2)/5)*5,hi=Math.ceil((Math.max(...series.flatMap(s=>s.values))+2)/5)*5,X=i=>36+i*420/Math.max(1,points.length-1),Y=v=>132-(v-lo)/(hi-lo)*106;return `<figure class="ct-trend"><figcaption>${ctMonths[plan.start]} = 100 · Comparable monthly growth</figcaption><svg viewBox="0 0 492 167" role="img" aria-label="${esc(scopeName(plan.ids))} cost and revenue indexed to ${ctMonths[plan.start]}">${[lo,(lo+hi)/2,hi].map(v=>`<path d="M36 ${Y(v)}H460" fill="none" stroke="#dce6f2" stroke-dasharray="3 4"/><text x="3" y="${Y(v)+4}">${v.toFixed(0)}</text>`).join('')}${series.map(s=>`<polyline points="${s.values.map((v,i)=>X(i)+','+Y(v)).join(' ')}" fill="none" stroke="${s.color}" stroke-width="2.6"/>${s.values.map((v,i)=>`<circle cx="${X(i)}" cy="${Y(v)}" r="3" fill="${s.color}"><title>${s.label}: ${v.toFixed(1)}</title></circle>`).join('')}`).join('')}${points.map((m,i)=>`<text x="${X(i)}" y="157" text-anchor="middle">${ctShort[m]}</text>`).join('')}</svg><div class="ct-trend-legend">${series.map(s=>`<span><i style="background:${s.color}"></i>${s.label}</span>`).join('')}</div></figure>`;}
function ctArtifactHtml(a){const p=a.ctPlan,d=a.ctArtifact,focus=p.focus==='support'?'support':'cost',rows=p.ids.map(id=>ctMetrics(id,p.start,p.end)),context=d.context||[];return `<div class="ct-document"><div class="ct-doc-tag">${d.kind==='request'?'UNSENT INFORMATION REQUEST':d.kind==='challenge'?'EVIDENCE & INTERPRETATION REVIEW':d.kind==='decision'?'CONFIRMED REVIEW RECORD':'LINKED OPERATING ANALYSIS'}</div>${d.kind==='decision'?`<h2>${esc(d.decision.text)}</h2><p>${esc(d.decision.rationale)}</p><dl><dt>Confirmed by</dt><dd>${esc(d.decision.owner)}</dd><dt>Revisit condition</dt><dd>${esc(d.decision.revisit)}</dd><dt>Decision ID</dt><dd>${d.decision.id}</dd></dl>`:d.kind==='request'?`<h2>Resolve the missing operating context.</h2><p>The aggregate data establishes the movement, not the business cause. Use these questions in the management review; this draft has not been sent.</p>${p.ids.map(id=>`<section><h3>${names[id]}</h3><p>${ctFact(id,p.start,p.end)}</p><ol>${ctReviewQuestions(id,p.start,p.end).map(q=>`<li>${esc(q)}</li>`).join('')}</ol></section>`).join('')}`:d.kind==='challenge'?`<h2>The numerical finding holds. Its explanation remains open.</h2>${p.ids.map(id=>ctChallengeHtml(id,p.start,p.end,context)).join('')}`:`<h2>${p.ids.length===1&&p.ids[0]==='northstar'&&p.end===3?'Revenue is catching up; the original cause is still unverified.':'A comparison grounded in the selected period.'}</h2><p>${rows.map(r=>`${names[r.id]}: ${p.focus==='support'?'Support cost '+pPct(data[r.id].support[p.end],data[r.id].support[p.start]):'people cost '+pPct(data[r.id].cost[p.end],data[r.id].cost[p.start])} versus revenue ${pPct(data[r.id].revenue[p.end],data[r.id].revenue[p.start])}.`).join(' ')}</p>${p.format!=='table'?ctTrend(p):''}`}
${d.kind!=='decision'?`<section><h3>Selected monthly values</h3><div class="as-table-wrap"><table><thead><tr><th>Company / month</th><th>${focus==='support'?'Support':'People cost'} ($m)</th><th>Revenue ($m)</th><th>People cost / revenue</th></tr></thead><tbody>${p.ids.map(id=>Array.from({length:p.end-p.start+1},(_,i)=>p.start+i).map(i=>`<tr><td>${names[id]} · ${ctShort[i]}</td><td>${data[id][focus][i].toFixed(2)}</td><td>${data[id].revenue[i].toFixed(2)}</td><td>${(data[id].cost[i]/data[id].revenue[i]*100).toFixed(1)}%</td></tr>`).join('')).join('')}</tbody></table></div></section>`:''}
${d.kind==='analysis'&&p.format==='report'?ctCostBridge(p):''}${d.decision&&d.kind!=='decision'?`<section class="ct-prior-judgment"><h3>Revisiting ${esc(d.decision.id)}</h3><p>${esc(d.decision.text)}</p><small>Review condition: ${esc(d.decision.revisit||'Compare the next publication.')}</small><p>The numerical movement does not establish the business cause. Record an updated judgment after reviewing the outstanding evidence.</p></section>`:''}${d.kind==='analysis'?`<section><h3>What to review next</h3>${p.ids.map(id=>`<p><strong>${names[id]}</strong> — ${esc(ctHypothesisFor(id,context))}</p>`).join('')}</section>`:''}
${context.length?`<details class="ct-evidence"><summary>Context captured with this version · ${context.length} entries</summary>${context.map(c=>`<p><span class="ct-type ${c.kind}">${ctKind(c.kind)}</span> ${esc(c.text)}<small>${esc(c.source)} · ${esc(c.asOf)}</small></p>`).join('')}</details>`:''}
<details class="ct-evidence"><summary>Source publications & reusable findings</summary><p>Monthly values in USD. Growth compares ${ctMonths[p.end]} with ${ctMonths[p.start]}. Support is included in total people cost. These are synthetic publications.</p>${(d.sources||[]).map(s=>`<p>${names[s.company]} · ${s.system}<small>${s.publication} · ${s.status}</small></p>`).join('')}${d.sourceBrief?`<p>Starting brief: ${esc(d.sourceBrief.value.title)} · captured v${d.sourceBrief.version+1}</p>`:''}${(d.findings||[]).map(f=>`<p>Finding ${f.id} · v${f.version}<small>${ctShort[f.start]}–${ctShort[f.end]} · ${esc(f.fact)}</small></p>`).join('')}</details></div>`;}
function ctCostBridge(plan){const rows=plan.ids.map(id=>ctMetrics(id,plan.start,plan.end)),total=rows.reduce((n,r)=>n+r.delta,0);return `<section><h3>Where the cost change sits</h3><p>Monthly people cost changed by $${Math.round(total*1000)}k across the selected companies from ${ctMonths[plan.start]} to ${ctMonths[plan.end]}. The bridge separates Support from the remaining departments.</p><div class="as-table-wrap"><table><thead><tr><th>Company</th><th>Support change</th><th>Other departments</th><th>Total change</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${names[r.id]}</td><td>$${Math.round(r.sd*1000)}k</td><td>$${Math.round((r.delta-r.sd)*1000)}k</td><td>$${Math.round(r.delta*1000)}k</td></tr>`).join('')}</tbody></table></div><p>These are changes in monthly cost, not cumulative spending. Payroll, service-volume and customer-level evidence are needed to explain the business drivers.</p></section>`;}
function pPct(a,b){return p(pct(a,b));}
function ctChallengeHtml(id,start=0,end=3,context=ctContextSnapshot([id],state.route==='work'?state.session:null)){const m=ctMetrics(id,start,end);return `<section class="ct-challenge-company"><h3>${names[id]}</h3><p>${ctFact(id,start,end)}</p><div class="ct-check-row"><span>${I('check')}Coverage</span><p>${ctMonths[start]}–${ctMonths[end]} aggregate publications are available.${id==='harbor'&&end===3?' September financial v1 remains approved despite a subsequent refresh timeout.':''}</p></div><div class="ct-check-row"><span>${I('check')}Definitions</span><p>Monthly USD amounts; a consistent baseline. Support is part of people cost. Cost / revenue is not operating margin.</p></div><div class="ct-check-row"><span>${I('circle-help')}Alternatives</span><p>${esc(ctHypothesisFor(id,context))}</p></div><div class="ct-check-row"><span>${I('file-question')}Missing evidence</span><p>${esc(ctReviewQuestions(id,start,end)[0])}</p></div><div class="ct-qualified"><strong>Suggested wording</strong><p>${id==='harbor'?'Revenue is growing faster than people cost; higher workforce productivity is not established.':id==='northstar'&&end===3?'The September figures indicate better cost absorption. They do not establish that customer rollout timing caused the earlier increase.':'The cost movement warrants follow-up. The available data does not establish overstaffing or an unplanned cost overrun.'}</p></div></section>`;}
const ctBaseCanvas=canvas;
canvas=function(){const a=current();let html=ctBaseCanvas();if(a.ctArtifact){html=html.replace('<div class="as-document"></div>','<div class="as-document">'+ctArtifactHtml(a)+'</div>');html=html.replace(' / June–'+endName(a)+' 2026',' / '+ctMonths[a.ctPlan.start]+'–'+ctMonths[a.ctPlan.end]+' 2026');}if(a.companyIds.length===1)html=html.replace('<div class="as-document">',ctFindingActions(a.companyIds[0],a.ctPlan?.end??monthIndex(a))+'<div class="as-document">');return html;};
