function ctOpenModal(type,value='',extra={}){ct.modal={type,value,...extra};if(type==='context'){const c=state.route==='work'?{ids:current().companyIds,end:current().ctPlan?.end??monthIndex(current()),label:taskTitle(state.session)}:assistantContext();ct.modal.ids=[...c.ids];ct.modal.company=c.ids[0];ct.modal.context=ctClone(c);}if(type==='adjust'){const t=feedTasks().find(x=>x.id===value);ct.modal.plan=ctClone(extra.plan||(t?ctPlan(t):ctTask().plan));ct.modal.original=ctClone(ct.modal.plan);ct.modal.draft='';}if(type==='decision'){const id=value||ctTask().ids[0],old=ctLatestDecision(id),end=state.route==='case'?2:state.route==='work'?(current().ctPlan?.end??monthIndex(current())):3;ct.modal.company=id;ct.modal.end=end;ct.modal.text=old?.text||'Keep this issue under review; the business cause is not yet established.';ct.modal.rationale=ctFact(id,0,end);ct.modal.revisit='Recheck Support cost, revenue and people-cost intensity after the next approved monthly publication.';ct.modal.owner='Operating partner · demo';ct.modal.next=end<3?'sep':'oct';ct.modal.createRoutine=true;}ctPaintModal(true);}
function ctCloseModal(){const d=root.querySelector('#ct-dialog');if(d?.open)d.close();d?.remove();ct.modal=null;}
function ctPaintModal(focus=false){if(!ct.modal)return;let d=root.querySelector('#ct-dialog');if(!d){d=document.createElement('dialog');d.id='ct-dialog';d.className='ct-dialog';root.append(d);d.addEventListener('cancel',e=>{e.preventDefault();ctCloseModal();});}const m=ct.modal,titles={context:'Working context',adjust:'Adjust this task',decision:'Record a judgment',challenge:'Challenge the finding',progress:'Task progress',queue:'Needs your input',reuse:'Finding added to your brief'};d.innerHTML=`<div class="ct-modal-head"><div><span class="ct-eyebrow">PORTFOLIO INTELLIGENCE</span><h2>${titles[m.type]||'Review'}</h2></div>${ctButton(I('x')+'<span class="as-sr">Close</span>','close')}</div><div class="ct-modal-body">${m.type==='context'?ctContextModal():m.type==='adjust'?ctAdjustModal():m.type==='decision'?ctDecisionModal():m.type==='progress'?ctProgressModal():m.type==='queue'?ctQueueModal():m.type==='challenge'?ctChallengeModal():''}</div>`;if(!d.open)d.showModal();ambientIcons();if(focus)d.querySelector('[data-ct="close"]')?.focus();}
function ctContextModal(){const m=ct.modal,id=m.company,entries=ctContextEntries([id]),decisions=ct.decisions.filter(d=>d.company===id),editing=m.editing||null;return `<div class="ct-context-scope"><label>Company<select id="ct-context-company">${m.ids.map(id=>`<option value="${id}" ${m.company===id?'selected':''}>${names[id]}</option>`).join('')}</select></label><span>${esc(m.context.label||'Current work')}<small>Company context is separate from the page filter.</small></span></div>${state.route!=='work'?`<details class="ct-evidence"><summary>Change Scout’s conversation scope</summary><div class="ct-checkboxes">${Object.keys(data).map(k=>`<label><input type="checkbox" name="ct-scout-scope" value="${k}" ${m.ids.includes(k)?'checked':''}>${names[k]}</label>`).join('')}</div><label class="ct-field">Analysis through<select id="ct-scout-end"><option value="aug" ${m.context.end==='aug'?'selected':''}>August</option><option value="sep" ${m.context.end==='sep'?'selected':''}>September</option></select></label>${ctButton('Apply to Scout','scout-scope')}</details>`:''}<div class="ct-context-list">${entries.map(c=>`<article><div><span class="ct-type ${c.kind}">${ctKind(c.kind)}</span><small>${esc(c.asOf)} · v${c.version}</small></div><p>${esc(c.text)}</p><small>${esc(c.source)}${c.kind==='assertion'?' · Recorded statement, not corroborated':''}</small>${['assertion','hypothesis'].includes(c.kind)?`<div class="ct-context-actions">${ctButton('Revise','revise-context',c.id)}${state.route==='work'?ctButton((ctTask().excluded||[]).includes(c.id)?'Include in task':'Exclude from task','exclude-context',c.id):''}</div>`:''}</article>`).join('')}</div>${!entries.some(c=>c.kind==='assertion')?'<p class="ct-empty-note">No management explanation has been captured. A hypothesis is not a source fact.</p>':''}<details class="ct-evidence" ${editing||m.contextDraft?'open':''}><summary>${editing?'Revise context · old versions are retained':'Add context for '+names[id]}</summary><form id="ct-context-form"><label class="ct-field">Type<select id="ct-context-kind"><option value="assertion" ${editing?.kind==='assertion'?'selected':''}>Management statement · uncorroborated</option><option value="hypothesis" ${editing?.kind==='hypothesis'?'selected':''}>Hypothesis · unverified</option></select></label><label class="ct-field">Statement<textarea id="ct-context-text" rows="3" required placeholder="Capture what was said or what should be tested…">${esc(editing?.text||m.contextDraft||'')}</textarea></label><label class="ct-field">Source / attribution<input id="ct-context-source" required value="${esc(editing?.source||'Added by you in this demo')}" placeholder="Who provided it, or which document?"></label><p class="ct-caption">Confirming records this statement. It does not make the explanation a verified data fact.</p><button class="as-button primary" type="button" data-ct="confirm-context">Confirm context</button></form>${ctButton('Use a sample management note','sample-context')}</details>${decisions.length?`<details class="ct-evidence"><summary>Judgment history · ${decisions.length}</summary>${decisions.slice().reverse().map(d=>`<article><strong>${d.id} · ${esc(d.text)}</strong><p>${esc(d.rationale)}</p><small>${esc(d.owner)} · ${new Date(d.at).toLocaleDateString('en-US')}<br>Revisit: ${esc(d.revisit)}</small>${d.outputId?ctButton('Open recorded judgment','open-output',d.outputId):''}</article>`).join('')}</details>`:''}<div class="ct-modal-footnote">Local demo memory · Original publications and past report versions remain unchanged.</div>`;}
function ctAdjustModal(){const m=ct.modal,p=m.plan;if(!p)return '<p>No plan selected.</p>';return `<p class="ct-lead">Describe a change, then review the actual plan before running.</p><div class="ct-adjust-prompt"><textarea id="ct-adjust-text" rows="2" placeholder="Only Northstar and Cedar, August to September, focus on Support, comparison table…">${esc(m.draft||'')}</textarea>${ctButton(I('sparkles')+' Update plan','interpret-plan')}</div>${m.error?`<p class="ct-form-error" role="alert">${esc(m.error)}</p>`:''}<div class="ct-checkboxes">${Object.keys(data).map(id=>`<label><input type="checkbox" data-ct-plan-company="${id}" ${p.ids.includes(id)?'checked':''}>${names[id]}</label>`).join('')}</div><div class="ct-form-grid"><label>From<select data-ct-plan="start">${[0,1,2].map(i=>`<option value="${i}" ${p.start===i?'selected':''}>${ctMonths[i]}</option>`).join('')}</select></label><label>Through<select data-ct-plan="end">${[1,2,3].map(i=>`<option value="${i}" ${p.end===i?'selected':''}>${ctMonths[i]}</option>`).join('')}</select></label><label>Focus<select data-ct-plan="focus"><option value="total" ${p.focus==='total'?'selected':''}>All people costs</option><option value="support" ${p.focus==='support'?'selected':''}>Customer Support</option></select></label><label>Output<select data-ct-plan="format">${['brief','table','report'].map(v=>`<option value="${v}" ${p.format===v?'selected':''}>${v==='brief'?'One-page brief':v==='table'?'Comparison table':'Analytical report'}</option>`).join('')}</select></label></div><div class="ct-approved-plan"><strong>Plan to execute</strong>${ctPlanSummary(p)}<p>${esc(ctPlanText(p))}</p>${p.source?`<small>Starting brief: ${esc(p.source.value.title)} · captured v${p.source.version+1}. Its original scope is ${esc(scopeName(p.source.value.companyIds))}; the new output uses the selected companies above.</small>`:''}</div><div class="ct-modal-actions">${ctButton('Cancel','close')}${ctButton('Run in background','execute-plan-bg').replace('<button ', '<button '+(m.error?'disabled ':''))}${ctButton('Run task','execute-plan','',true).replace('<button ', '<button '+(m.error?'disabled ':''))}</div>`;}
function ctDecisionModal(){const m=ct.modal,id=m.company;return `<p class="ct-lead">${names[id]} · ${ctIssueNames[id]}</p><form id="ct-decision-form"><label class="ct-field">Judgment<textarea id="ct-decision-text" rows="3" required>${esc(m.text)}</textarea></label><label class="ct-field">Evidence and rationale<textarea id="ct-decision-rationale" rows="3" required>${esc(m.rationale)}</textarea></label><p class="ct-caption">Business cause remains unverified unless supporting evidence is supplied. This records your review decision, not an instruction to a company.</p><label class="ct-field">Owner<input id="ct-decision-owner" value="${esc(m.owner)}" required></label><label class="ct-field">Revisit when<textarea id="ct-decision-revisit" rows="2" required>${esc(m.revisit)}</textarea></label><div class="ct-followup-choice"><label><input type="checkbox" id="ct-create-routine" ${m.createRoutine?'checked':''}> Create or update a linked follow-up routine</label><label class="ct-field">Next publication<select id="ct-decision-next"><option value="sep" ${m.next==='sep'?'selected':''}>September · available for simulation</option><option value="oct" ${m.next==='oct'?'selected':''}>October · waiting for data</option></select></label></div><div class="ct-modal-actions">${ctButton('Cancel','close')}<button class="as-button primary" type="button" data-ct="confirm-decision">Confirm judgment &amp; follow-up</button></div></form>`;}
function ctProgressModal(){const key=ct.modal.value||state.session,t=ctTask(key);return `<p class="ct-lead">${esc(t.goal)}</p><div class="ct-status-pill ${t.status}">${ctLabels[t.status]} · ${t.step||0}/3 analysis steps</div><p>${esc(t.next)}</p><ol class="ct-progress-steps">${['Read source publications and relevant context','Calculate the selected comparison','Prepare the output and open review questions'].map((s,i)=>`<li class="${i<t.step?'done':''}">${I(i<t.step?'circle-check':'circle')}<span>${s}</span></li>`).join('')}</ol><div class="ct-modal-actions">${t.status==='running'?ctButton('Pause','pause-task',key):['waiting_data','monitoring','resolved'].includes(t.status)?'':ctButton(t.status==='paused'?'Resume':'Continue in background','start-task',key)}${ctButton('Take over in chat','takeover',key)}${t.outputId?ctButton('Open output','open-output',t.outputId,true):''}</div><p class="ct-caption">Simulated background work continues while this page stays open. Closing or reloading pauses work; no server scheduler is connected.</p><details class="ct-evidence" open><summary>Activity &amp; context</summary>${t.activity.slice().reverse().map(a=>`<p>${esc(a.text)}<small>${new Date(a.at).toLocaleTimeString('en-US')}</small></p>`).join('')}${t.contextIds?.length?`<small>${t.contextIds.length} context entries captured for this task.</small>`:''}</details>`;}
function ctQueueModal(){const rows=Object.values(ct.tasks).filter(t=>t.ids.some(id=>companyScope().includes(id))&&['review','waiting_info'].includes(t.status));return rows.length?rows.map(t=>`<article class="ct-queue-row"><span class="ct-type ${t.status}">${ctLabels[t.status]}</span><h3>${esc(t.goal)}</h3><p>${esc(t.next)}</p>${ctButton('Open task','open-task',t.key,true)}${t.issue?ctButton(t.status==='waiting_info'?'Add context':'Record judgment',t.status==='waiting_info'?'context':'decision',t.status==='waiting_info'?t.key:t.issue):''}</article>`).join(''):'<p>No items require your input in the selected companies.</p>';}
function ctChallengeModal(){const [id,endString]=ct.modal.value.split(':'),end=Number(endString||2);return `<p class="ct-lead">A focused check of the evidence, definitions and alternative explanations.</p>${ctChallengeHtml(id,0,end)}<div class="ct-modal-actions">${ctButton('Add to brief','reuse-brief',id+':'+end)}${ctButton('Save review in Workspace','save-challenge',id+':'+end,true)}</div>`;}
function ctConfirmContext(){const m=ct.modal,text=root.querySelector('#ct-context-text').value.trim(),source=root.querySelector('#ct-context-source').value.trim(),kind=root.querySelector('#ct-context-kind').value;if(!text||!source)return;const old=m.editing&&ct.contexts.find(c=>c.id===m.editing.id),id=ctId('CTX');if(old){old.superseded=id;for(const task of Object.values(ct.tasks))if(task.excluded?.includes(old.id))task.excluded.push(id);}ct.contexts.push({id,company:m.company,kind,text,source,asOf:new Date().toISOString().slice(0,10),version:(old?.version||0)+1,previous:old?.id||null,confirmedBy:'You · demo',superseded:null});const task=ctTask(state.route==='work'&&current().companyIds.includes(m.company)?state.session:ctEnsureIssue(m.company));if(!['running','paused'].includes(task.status)){task.next='New context has been recorded. Review it alongside the source facts before changing the judgment.';task.status='review';task.contextIds=ctContextSnapshot(task.ids,task.key).map(c=>c.id);}ctActivity(task,'Recorded '+ctKind(kind)+'. It remains separate from verified source facts.');m.editing=null;m.contextDraft='';ctSave();ctPaintModal();}
function ctConfirmDecision(){const m=ct.modal,id=m.company,key=ctEnsureIssue(id),text=root.querySelector('#ct-decision-text').value.trim(),rationale=root.querySelector('#ct-decision-rationale').value.trim(),owner=root.querySelector('#ct-decision-owner').value.trim(),revisit=root.querySelector('#ct-decision-revisit').value.trim(),next=root.querySelector('#ct-decision-next').value,make=root.querySelector('#ct-create-routine').checked;if(!text||!rationale||!owner||!revisit)return;const d={id:ctId('DEC'),company:id,taskKey:key,caseNo:caseDefs[id].no,text,rationale,owner,revisit,next,at:new Date().toISOString(),end:m.end,source:ctFinding(id,m.end),context:ctContextSnapshot([id],key)};ct.decisions.push(d);const plan={ids:[id],start:0,end:m.end,focus:'total',format:'brief',issue:id};d.outputId=ctAddArtifact(key,plan,'decision',{decision:d});const t=ctTask(key);t.status=make?'monitoring':'resolved';t.needsRevisit=make&&next==='sep';t.next=make?(next==='sep'?'September data is available. Run the linked routine to revisit this judgment.':'Waiting for October publication and the next follow-up review.'):'Judgment recorded. Reopen this issue when new evidence changes the picture.';ctActivity(t,'Judgment '+d.id+' confirmed by '+owner);if(make)ctUpsertRoutine(d);ctCloseModal();state.notice='Judgment recorded'+(make?' and follow-up routine linked.':'.');render();ctSave();}
function ctUpsertRoutine(d){let rule=ops.rules.find(r=>r.ctLink?.company===d.company);const linked={company:d.company,decisionId:d.id,taskKey:d.taskKey,caseNo:d.caseNo,findingId:d.source.id,findingVersion:d.source.version,decisionSnapshot:ctClone(d)};if(rule){rule.version++;Object.assign(rule,{goal:d.revisit,end:d.next,companyIds:[d.company],ctLink:linked,enabled:true});}else{rule={id:'followup-'+d.company,name:names[d.company].split(' ')[0]+' · '+ctIssueNames[d.company],goal:d.revisit,template:'scan',companyIds:[d.company],trigger:'publication',day:5,end:d.next,threshold:8,enabled:true,version:1,ctLink:linked};ops.rules.unshift(rule);}return rule;}
const ctBaseMakeRun=makeRun;
makeRun=function(rule,at=Date.now(),kind='Manual simulation'){if(!rule.ctLink||rule.companyIds.length!==1||rule.companyIds[0]!==rule.ctLink.company){const clean=ctClone(rule);delete clean.ctLink;return ctBaseMakeRun(clean,at,kind);}const cfg=ctClone(rule),rid='RUN-'+String(++ops.runSeq).padStart(3,'0'),link=cfg.ctLink,key=link.taskKey,t=ctTask(key),available=cfg.end!=='oct',run={id:rid,ruleId:cfg.id,config:cfg,at,kind,status:available?'Completed':'Waiting for data',source:available?'DEMO-'+cfg.end.toUpperCase()+'-2026-v1':null,mapping:'Demo mapping v1',rows:[],outputId:null,taskKey:key,ctDecision:ctClone(link.decisionSnapshot),ctContext:ctContextSnapshot(cfg.companyIds,key)};
 if(available){const end=cfg.end==='aug'?2:3,plan={ids:[...cfg.companyIds],start:0,end,focus:'total',format:cfg.template==='brief'?'brief':'report',issue:link.company,goal:cfg.goal,contextSnapshot:ctClone(run.ctContext)},metric=ctMetrics(link.company,0,end);run.rows=cfg.companyIds.map(id=>{const x=ctMetrics(id,0,end);return {...x,name:names[id],flag:x.gap>=cfg.threshold};});ctPause(key,false);run.summary=link.company==='northstar'&&end===3?'Improvement signal; judgment still open. Support remained $720k, revenue rose 8.6% from August and people cost rose 0.8%. The June-baseline growth gap narrowed from 13.0 pp to 5.0 pp.':ctFact(link.company,0,end)+' Review the prior judgment before drawing a business conclusion.';run.outputId=ctAddArtifact(key,plan,'analysis',{runId:rid,decision:link.decisionSnapshot,findings:cfg.companyIds.map(id=>ctFinding(id,end))});t.outputId=run.outputId;t.plan=ctClone(plan);t.status='review';t.needsRevisit=true;t.next='Review '+rid+' against judgment '+link.decisionId+'. The business explanation remains unverified.';t.step=3;run.steps=[['check','Load the linked judgment and finding',link.decisionId+' · '+link.findingId+' v'+link.findingVersion],['check','Read approved publication',run.source+' · '+opScope(cfg.companyIds)],['check','Compare with the previous review',run.summary],['check','Save a new follow-up in the same task','Task '+key+' · '+rid+' · '+link.decisionId]];
 }else{run.summary='October is not available. The linked judgment remains open; no October analysis or artifact was produced.';run.steps=[['check','Load the linked review decision',link.decisionId],['clock-3','Wait for October publication','Latest approved data ends in September.'],['minus','No result generated','The prior finding and judgment are preserved.']];t.status='waiting_data';t.next=run.summary;}ops.runs.unshift(run);ctActivity(t,rid+': '+run.summary);ctSave();return run;};

const ctBaseEditRule=editRulePage;
