const ctBaseSaveRule=saveRule;
saveRule=function(){const editor=ops.editor,id=editor?.id,link=editor?.ctLink;ctBaseSaveRule();if(ops.editor||!link)return;const r=ops.rules.find(r=>r.id===id);if(r&&(r.companyIds.length!==1||r.companyIds[0]!==link.company)){delete r.ctLink;state.notice='Configuration saved. Future runs use the new company scope; the prior investigation, judgment and run history are preserved.';}render();ctSave();};

const ctBaseRuleCard=ruleCard;
ruleCard=function(r){let html=ctBaseRuleCard(r);if(r.ctLink)html=html.replace('<div class="op-rule-bottom">',`<div class="ct-routine-link">${I('link')}Case ${r.ctLink.caseNo} · ${r.ctLink.findingId} v${r.ctLink.findingVersion} · ${r.ctLink.decisionId}${ctButton('Open investigation','open-task',r.ctLink.taskKey)}</div><div class="op-rule-bottom">`);return html;};
const ctBaseRunPage=runDetailPage;
runDetailPage=function(){const r=ops.runs.find(r=>r.id===ops.selectedRun);let html=ctBaseRunPage();if(r?.config.ctLink){const d=r.ctDecision;html=html.replace('<h2>Result</h2>',`<div class="ct-run-judgment"><span class="ct-eyebrow">LINKED JUDGMENT · ${d.id}</span><p>${esc(d.text)}</p><small>${esc(d.owner)} · ${esc(d.revisit)}</small>${ctButton('Continue original investigation','open-task',r.taskKey)}</div><h2>Result</h2>`);}return html;};
function ctReuse(id,end){const f=ctFinding(id,end),reuseKey=f.id+':'+f.version;if(ct.reuse[reuseKey]){ctCloseModal();openHubArtifact(ct.reuse[reuseKey]);return;}const key=ctEnsureIssue(id),plan={ids:[id],start:0,end,focus:'total',format:'brief',issue:id,goal:'Reuse the source-backed finding in a partner brief'},out=ctAddArtifact(key,plan,'analysis',{findings:[f],reused:true});ct.reuse[reuseKey]=out;ctActivity(ctTask(key),'Added '+f.id+' v'+f.version+' to a partner brief.');ctCloseModal();openHubArtifact(out);ctSave();}
const ctBaseDashboard=dashboardPage;
dashboardPage=function(){let html=ctBaseDashboard().replace('Layout changes are kept for this preview.','Layout changes are saved in this browser.');const pins=ct.pins.filter(x=>x.company&&companyScope().includes(x.company));if(pins.length)html=html.replace('</section>',`<section class="ct-pinned-findings"><h2>Tracked findings</h2><div>${pins.map(x=>{const f=ct.findings[x.findingId]?.versions.find(v=>v.version===x.version),m=ctMetrics(x.company,0,f.end);return `<article><span>${names[x.company]} · ${x.findingId} v${x.version}</span><h3>${m.ratio.toFixed(1)}%</h3><p>People cost / revenue · ${ctMonths[f.end]}</p><small>Fixed source snapshot · Jun–${ctShort[f.end]} 2026</small>${ctButton('Open finding','open-finding',x.company+':'+f.end)}</article>`;}).join('')}</div></section></section>`);return html;};
const ctBasePageContext=pageContext;
