const ctBasePetBubble=petBubble;
petBubble=function(c){let h=ctBasePetBubble(c);if(h&&!['thinking'].includes(ambient.status)&&!['confirm','starting','listening','stopping'].includes(ambient.voice.state)){h+=`<button type="button" class="ct-pet-context" data-ct="context">${I('book-open')}Context · ${esc(scopeName(c.ids))}${I('chevron-right')}</button>`;}return h;};
const ctBaseAssistantPaint=assistantPaint;
assistantPaint=function(){ctBaseAssistantPaint();const dock=root.querySelector('#aa-form');if(dock&&!dock.querySelector('.ct-dock-context')){const c=assistantContext();dock.insertAdjacentHTML('afterbegin',`<button type="button" class="ct-dock-context" data-ct="context" title="Inspect or correct Scout’s working context">${I('book-open')}<span>${esc(scopeName(c.ids))} · ${esc(contextPeriod(c))}</span>${I('chevron-down')}</button>`);ambientIcons();positionAssistant();}};
function ctAnswer(text,c){
 const q=text.toLowerCase();if(!/last review|last time|decision|remember|launch|rollout|planned|cause|why|improv|changed|stabili|catching|上次|判断|记得|解释|原因|上线|提前|变化|改善|稳定/.test(q))return null;
 const request=ctResolveInput(text,{ids:c.ids,start:c.start??0,end:ctEndIndex(c.end)});
 if(request.error)return request.error;const plan=request.plan,key=c.taskKey||(state.route==='work'?state.session:null);
 if(c.end==='oct'&&!/september|august|九月|八月/.test(q))return 'October data is not available. The latest approved publication ends in September. No October calculation has been produced.';
 return plan.ids.map(id=>{const entries=ctContextSnapshot([id],key),decision=ctLatestDecision(id),assertions=entries.filter(c=>c.kind==='assertion');
 if(/last review|last time|decision|remember|上次|判断|记得/.test(q))return names[id]+': '+(decision?`The recorded judgment (${decision.id}) was: ${decision.text} Revisit condition: ${decision.revisit} ${assertions.length?'Management context is also recorded; it remains uncorroborated.':'No management explanation is included in this context.'}`:'No judgment has been recorded for this company yet.');
 if(/launch|rollout|planned|cause|why|解释|原因|上线|提前/.test(q))return names[id]+': '+ctFact(id,plan.start,plan.end)+' '+(assertions.length?'Recorded management statement: “'+assertions.at(-1).text+'” This has not been independently corroborated.':ctHypothesisFor(id,entries))+' '+ctReviewQuestions(id,plan.start,plan.end)[0];
 const d=data[id],end=plan.end,prior=Math.max(0,end-1);return names[id]+': '+ctFact(id,plan.start,end)+` In ${ctMonths[end]}, revenue changed ${pPct(d.revenue[end],d.revenue[prior])} from ${ctMonths[prior]}, while people cost changed ${pPct(d.cost[end],d.cost[prior])}. Support was $${Math.round(d.support[end]*1000)}k versus $${Math.round(d.support[prior]*1000)}k.`+(decision?' This revisits '+decision.id+': '+decision.text:' The interpretation still needs evidence.');
 }).join('\n\n');
}

const ctBaseCompleteAmbient=completeAmbientRequest;
completeAmbientRequest=function(input){
 const text=(input??ambient.draft).trim(),q=text.toLowerCase(),c=ctClone(assistantContext());
 const resolved=ctResolveInput(text,{ids:c.ids,start:c.start??0,end:ctEndIndex(c.end)});
 if(!resolved.error){c.ids=resolved.plan.ids;c.start=resolved.plan.start;c.end=ctShort[resolved.plan.end].toLowerCase();if(c.caseId&&!c.ids.includes(c.caseId))c.caseId=null;if(c.ids.length===1)c.caseId=c.ids[0];setAssistantContext(c);}
 if(/remember that|record context|记住|记录背景/.test(q)){pushAmbient('user',text,{context:ctClone(c)});pushAmbient('agent','Review the proposed context before saving. Recording a statement does not verify its explanation.',{context:ctClone(c)});ctOpenModal('context');ct.modal.contextDraft=text.replace(/remember that|record context|记住|记录背景/ig,'').trim();ctPaintModal();ambient.draft='';ctSave();return;}
 const deliverable=ctWantsDeliverable(q);
 const answer=resolved.error||(!deliverable&&ctAnswer(text,{...c,taskKey:ambient.taskKey}));
 if(answer){ambient.draft='';pushAmbient('user',text,{context:ctClone(c)});pushAmbient('agent',answer,{context:ctClone(c),short:shortText(answer,420),sources:resolved.error?'No result generated':'Approved publications and recorded company context',resume:c.ids.length===1?ctEnsureIssue(c.ids[0]):null});assistantPaint();ctSave();return;}
 ctBaseCompleteAmbient(text);ctSave();
};
const ctBaseRunRequest=runRequest;
runRequest=function(text){const q=text.trim(),t=ctTask();if(!q)return;if(/record.*judgment|keep monitoring|记录判断|继续跟踪/.test(q.toLowerCase())&&t.ids.length===1){state.messages.push({role:'user',text:q});state.draft='';ctOpenModal('decision',t.ids[0]);return;}if(/challenge|质疑|复核/.test(q.toLowerCase())&&t.ids.length===1){state.messages.push({role:'user',text:q});state.draft='';const plan={ids:t.ids,start:current().ctPlan?.start??0,end:current().ctPlan?.end??monthIndex(current()),focus:'total',format:'report',issue:t.issue};t.outputId=ctAddArtifact(state.session,plan,'challenge');t.status='review';render();return;}const answer=!ctWantsDeliverable(q)&&ctAnswer(q,{ids:current().companyIds,start:current().ctPlan?.start??0,end:current().ctPlan?.end??current().end,taskKey:state.session});if(answer){state.messages.push({role:'user',text:q});state.draft='';recordAgent(answer,'Company context and source facts kept separate',null);render();ctSave();return;}if(current().ctArtifact){const parsed=ctInterpret(q,current().ctPlan);state.messages.push({role:'user',text:q});state.draft='';if(parsed.error){recordAgent(parsed.error,'No output changed',null);render();return;}const plan=parsed.plan;plan.taskKey=state.session;plan.origin='workspace-'+ctId('EDIT');if(plan.ids.join(',')!==current().companyIds.join(',')){recordAgent('The new output uses '+scopeName(plan.ids)+'. Earlier versions keep their original scope.','Explicit scope change',null);}t.ids=plan.ids;t.issue=plan.ids.length===1?plan.ids[0]:null;t.plan=plan;t.outputId=ctAddArtifact(state.session,plan,plan.action==='request'?'request':'analysis');t.status=plan.action==='request'?'waiting_info':'review';render();ctSave();return;}ctBaseRunRequest(text);if(t.status==='running')ctPause(state.session);if(taskOutputs(state.session).length&&t.status==='ready'){t.status='review';t.next='Review the result; generating a report does not resolve the investigation.';}ctSave();};
const ctBaseScopeApply=applyTaskCompanyScope;
applyTaskCompanyScope=function(ids){ids=ids.filter(id=>Object.hasOwn(data,id));if(!ids.length){state.notice='Choose at least one company.';render();return;}if(current().ctArtifact){const next=ctClone(current().ctPlan);next.ids=[...ids];next.issue=ids.length===1?ids[0]:null;next.taskKey=state.session;ctCapturePlanContext(next);const t=ctTask();ctPause(state.session);t.ids=[...ids];t.issue=next.issue;t.plan=next;t.outputId=ctAddArtifact(state.session,next,current().ctArtifact.kind==='decision'?'analysis':current().ctArtifact.kind);t.status='review';state.notice='New scoped output created. Prior artifacts and drafts are retained.';render();ctSave();return;}ctBaseScopeApply(ids);const t=ctTask();t.ids=[...ids];t.issue=ids.length===1?ids[0]:null;ctSave();};
function ctRender(){render();if(ct.modal?.type==='progress')ctPaintModal();ctSave();}
function ctOpenTask(key){ctCloseModal();resumeTask(key);}
function ctHandle(action,value){const m=ct.modal;
 if(action==='close'){ctCloseModal();return;}
 if(action==='home-filter'){feedState.homeFilter=value;render();ctSave();return;}
 if(action==='home-preview'){const entry=ctHomeEntries().find(e=>e.key===value);if(!entry)return;feedState.open['home:'+value]=!feedState.open['home:'+value];const card=[...root.querySelectorAll('[data-home-card]')].find(c=>c.dataset.homeCard===value);if(card)card.outerHTML=ctHomeCard(entry);ambientIcons();[...root.querySelectorAll('[data-ct="home-preview"]')].find(b=>b.dataset.ctValue===value)?.focus({preventScroll:true});ctSave();return;}
 if(action==='context'){if(value&&taskSnapshot(value)){if(state.route!=='work'||state.session!==value)resumeTask(value);}ctOpenModal('context',value);}
 else if(action==='confirm-context')ctConfirmContext();
 else if(action==='confirm-decision')ctConfirmDecision();
 else if(action==='queue')ctOpenModal('queue');
 else if(action==='adjust')ctOpenModal('adjust',value);
 else if(action==='run-plan'){const t=feedTasks().find(t=>t.id===value);if(t?.completedRun?.id)openHubArtifact(t.completedRun.id);else if(t)ctLaunch(ctPlan(t));}
 else if(action==='interpret-plan'){m.draft=root.querySelector('#ct-adjust-text').value;const r=ctInterpret(m.draft,m.plan);m.error=r.error||'';if(r.plan)m.plan=r.plan;ctPaintModal();}
 else if(action==='execute-plan'||action==='execute-plan-bg'){if(m.error)return;if(!m.plan.ids.length||m.plan.start>=m.plan.end){m.error='Select at least one company and an end month after the start month.';ctPaintModal();return;}m.plan.issue=m.plan.ids.length===1?m.plan.ids[0]:null;ctCapturePlanContext(m.plan);ctLaunch(m.plan,action==='execute-plan-bg');}
 else if(action==='sample-context'){m.contextDraft='Illustrative management note: Support capacity was added ahead of a planned customer rollout.';m.editing={kind:'assertion',text:m.contextDraft,source:'Sample note added in this demo'};ctPaintModal();}
 else if(action==='revise-context'){m.editing=ctClone(ct.contexts.find(c=>c.id===value));ctPaintModal();}
 else if(action==='exclude-context'){const t=ctTask();t.excluded??=[];t.excluded=t.excluded.includes(value)?t.excluded.filter(id=>id!==value):[...t.excluded,value];if(!['running','paused'].includes(t.status))t.contextIds=ctContextSnapshot(t.ids,t.key).map(c=>c.id);ctActivity(t,(t.excluded.includes(value)?'Excluded ':'Included ')+value+' in task context.');ctPaintModal();ctSave();}
 else if(action==='scout-scope'){const ids=[...root.querySelectorAll('[name="ct-scout-scope"]:checked')].map(x=>x.value);if(!ids.length)return;const c={...assistantContext(),ids,end:root.querySelector('#ct-scout-end').value,caseId:ids.length===1?ids[0]:null};setAssistantContext(c);m.ids=ids;m.company=ids[0];m.context=c;ctPaintModal();assistantPaint();ctSave();}
 else if(action==='decision')ctOpenModal('decision',value);
 else if(action==='progress')ctOpenModal('progress',value);
 else if(action==='start-task'){ctStart(value);if(m?.type==='progress')ctPaintModal();}
 else if(action==='pause-task'){ctPause(value);ctRender();}
 else if(action==='takeover'){ctPause(value);ctOpenTask(value);root.querySelector('#as-input')?.focus();}
 else if(action==='open-task')ctOpenTask(value);
 else if(action==='open-output'){ctCloseModal();openHubArtifact(Number(value));}
 else if(action==='challenge')ctOpenModal('challenge',value);
 else if(action==='save-challenge'){const [id,e]=value.split(':'),key=ctEnsureIssue(id),plan={ids:[id],start:0,end:Number(e),focus:'total',format:'report',issue:id};const out=ctAddArtifact(key,plan,'challenge');ctTask(key).status='review';ctTask(key).outputId=out;ctCloseModal();openHubArtifact(out);ctSave();}
 else if(action==='reuse-brief'){const [id,end]=value.split(':');ctReuse(id,Number(end));}
 else if(action==='pin-finding'){const [id,end]=value.split(':'),f=ctFinding(id,Number(end));if(!ct.pins.some(p=>p.findingId===f.id&&p.version===f.version))ct.pins.push({company:id,findingId:f.id,version:f.version});state.notice='Finding '+f.id+' v'+f.version+' pinned in Dashboards with its source snapshot.';ctSave();ctRender();}
 else if(action==='open-finding'){const [id,end]=value.split(':');ctOpenModal('challenge',id+':'+end);}
}
root.addEventListener('click',e=>{const b=e.target.closest('[data-ct]');if(!b||b.disabled)return;e.preventDefault();e.stopImmediatePropagation();ctHandle(b.dataset.ct,b.dataset.ctValue||'');},true);
root.addEventListener('submit',e=>{if(e.target.id==='ct-context-form'){e.preventDefault();ctConfirmContext();}else if(e.target.id==='ct-decision-form'){e.preventDefault();ctConfirmDecision();}});
root.addEventListener('change',e=>{const m=ct.modal;if(!m)return;if(e.target.id==='ct-context-company'){m.company=e.target.value;m.editing=null;m.contextDraft='';ctPaintModal();}else if(e.target.hasAttribute('data-ct-plan-company')){m.plan.ids=[...root.querySelectorAll('[data-ct-plan-company]:checked')].map(x=>x.dataset.ctPlanCompany);m.error='';ctPaintModal();}else if(e.target.dataset.ctPlan){const k=e.target.dataset.ctPlan;m.plan[k]=['start','end'].includes(k)?Number(e.target.value):e.target.value;m.error='';ctPaintModal();}});
root.addEventListener('input',e=>{if(ct.modal?.type==='adjust'&&e.target.id==='ct-adjust-text')ct.modal.draft=e.target.value;if(['as-input','aa-input'].includes(e.target.id))ctSave();});

let ctSaveTimer=null;
function ctSnapshot(){stashSession();const copy=ctClone(ct);delete copy.modal;delete copy.storage;delete copy.loaded;return {schema:1,ct:copy,state:ctClone(state),ops:ctClone(ops),seq,ambient:{messages:ctClone(ambient.messages),nextId:ambient.nextId,tasks:ctClone(ambient.tasks),syncedMessages:ctClone(ambient.syncedMessages),draft:ambient.draft},feedState:ctClone(feedState)};}
function ctSave(){if(!ct.loaded)return;clearTimeout(ctSaveTimer);ctSaveTimer=setTimeout(()=>{try{window.parent.postMessage({type:'pe-continuity-save',payload:ctSnapshot()},'*');}catch{ct.storage='unavailable';}},180);}
const ctBaseRenderHub=renderHub;
renderHub=function(){ctBaseRenderHub();ctSave();};
const ctBaseAutomations=automationsPage;
automationsPage=function(){return ctBaseAutomations().replace('Changes last while this preview is open.','Demo work is saved in this browser; no server scheduler is connected.');};
function ctInitialize(){
 for(const id of Object.keys(data)){ct.contexts.push({id:'CTX-'+id+'-fact',company:id,kind:'fact',text:ctFact(id,0,2),source:'Approved synthetic HR + financial publications · Jun–Aug 2026',asOf:'2026-08-31',version:1,superseded:null});ct.contexts.push({id:'CTX-'+id+'-hypothesis',company:id,kind:'hypothesis',text:ctHypotheses[id],source:'Agent interpretation · not verified',asOf:'2026-08-31',version:1,superseded:null});const t=ctTask(ctEnsureIssue(id));t.goal=names[id]+' · '+ctIssueNames[id];t.status=id==='cedar'?'waiting_info':'ready';t.next=id==='cedar'?'The cost bridge is available; management context has not been supplied.':'September data is ready to compare with the August finding.';ctActivity(t,'Seeded demo investigation based on the August operating review.');ctFinding(id,2);}
 const key=ctEnsureIssue('northstar'),d={id:'DEC-NORTHSTAR-AUG',company:'northstar',taskKey:key,caseNo:'014',text:'Keep the Support expansion under review; do not conclude its cause yet.',rationale:'Support explained $320k of the $360k June–August increase. Staffing and customer-rollout evidence were not supplied.',owner:'Operating partner · sample review',revisit:'When September is approved, check whether Support cost stabilizes and revenue catches up.',next:'sep',at:'2026-09-05T13:00:00Z',end:2,source:ctFinding('northstar',2),context:ctContextSnapshot(['northstar']),seeded:true};ct.decisions.push(d);const rule=ctUpsertRoutine(d);const old=ops.rules.find(r=>r.id==='watch');if(old)ops.rules=ops.rules.filter(r=>r.id!=='watch');ctTask(key).needsRevisit=true;
 window.addEventListener('message',e=>{if(e.source!==window.parent)return;if(e.data?.type==='pe-continuity-loaded'&&!ct.loaded){const saved=e.data.payload;try{if(saved?.schema===1&&saved.state?.artifacts?.length&&saved.state.artifacts.every(a=>a.versions?.length&&a.versions.every(v=>Array.isArray(v.companyIds)&&v.companyIds.every(id=>Object.hasOwn(data,id))))&&saved.ct?.schema===1){Object.assign(state,saved.state);Object.assign(ops,saved.ops);Object.assign(ct,saved.ct);seq=Math.max(saved.seq||1,...state.artifacts.map(a=>a.id));if(saved.ambient){Object.assign(ambient,saved.ambient);ambient.activeMessageId=null;ambient.taskKey=null;ambient.pageKey='';ambient.override=null;ambient.status='idle';ambient.open=false;}if(saved.feedState)Object.assign(feedState,saved.feedState);state.route='home';state.lastPageRoute=null;for(const t of Object.values(ct.tasks)){if(t.status==='running'){t.status='paused';t.token++;t.next='Page reopened. Resume the saved analysis from its last completed step.';}}}}catch{state.notice='Saved demo state could not be restored; this visit uses the seeded examples.';}ct.modal=null;ct.loaded=true;ct.storage=e.data.available?'saved':'unavailable';render();}else if(e.data?.type==='pe-continuity-saved'){ct.storage=e.data.ok?'saved':'unavailable';root.querySelectorAll('.ct-storage').forEach(n=>n.textContent=e.data.ok?'Demo work saved in this browser':'Demo work lasts for this visit');}});
 window.addEventListener('pagehide',()=>{if(ct.loaded)window.parent.postMessage({type:'pe-continuity-save',payload:ctSnapshot()},'*');});window.parent.postMessage({type:'pe-continuity-load'},'*');setTimeout(()=>{if(!ct.loaded)window.parent.postMessage({type:'pe-continuity-load'},'*');},500);
}
